-- Persisted application tables from Pocketmark 1.3.4 for offline migration tests.
CREATE TABLE account_setup(id INTEGER PRIMARY KEY CHECK(id=1), allowed INTEGER NOT NULL);
CREATE TABLE account(id INTEGER PRIMARY KEY CHECK(id=1),username TEXT NOT NULL,salt TEXT NOT NULL,hash TEXT NOT NULL);
CREATE TABLE sessions(id INTEGER PRIMARY KEY AUTOINCREMENT,hash TEXT NOT NULL UNIQUE,expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL DEFAULT 0, last_used_at INTEGER NOT NULL DEFAULT 0, confirmed_at INTEGER NOT NULL DEFAULT 0, idle_minutes INTEGER NOT NULL DEFAULT 0, device TEXT NOT NULL DEFAULT '', recovery_until INTEGER NOT NULL DEFAULT 0);
CREATE TABLE api_tokens(id INTEGER PRIMARY KEY,name TEXT NOT NULL,hash TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), last_used_at TEXT NOT NULL DEFAULT '', profile TEXT NOT NULL DEFAULT 'full' CHECK(profile IN ('read','capture','sync','full')), expires_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE mfa(
 id INTEGER PRIMARY KEY CHECK(id=1), secret BLOB NOT NULL DEFAULT X'',
 generation INTEGER NOT NULL DEFAULT 0, last_counter INTEGER NOT NULL DEFAULT -1,
 restored INTEGER NOT NULL DEFAULT 0 CHECK(restored IN (0,1)));
CREATE TABLE mfa_recovery(hash TEXT PRIMARY KEY);
CREATE TABLE library_metadata(id INTEGER PRIMARY KEY CHECK(id=1),created_at TEXT NOT NULL);
CREATE TABLE collections(id INTEGER PRIMARY KEY, name TEXT NOT NULL, parent_id INTEGER REFERENCES collections(id) ON DELETE SET NULL, description TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT '');
CREATE TABLE compat_tags(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT '');
CREATE TABLE links(
 id INTEGER PRIMARY KEY, url TEXT NOT NULL UNIQUE, title TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '',
 collection_id INTEGER REFERENCES collections(id) ON DELETE SET NULL, tags TEXT NOT NULL DEFAULT '[]', favorite INTEGER NOT NULL DEFAULT 0, read INTEGER NOT NULL DEFAULT 0,
 status TEXT NOT NULL DEFAULT 'pending', error TEXT NOT NULL DEFAULT '', content TEXT NOT NULL DEFAULT '', archive BLOB,
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE TABLE annotations(id INTEGER PRIMARY KEY, link_id INTEGER NOT NULL REFERENCES links(id) ON DELETE CASCADE, quote TEXT NOT NULL, start_offset INTEGER NOT NULL, end_offset INTEGER NOT NULL, note TEXT NOT NULL DEFAULT '', color TEXT NOT NULL DEFAULT 'yellow', created_at TEXT NOT NULL);
CREATE TABLE thumbnails(link_id INTEGER PRIMARY KEY REFERENCES links(id) ON DELETE CASCADE, data BLOB NOT NULL);
CREATE TABLE assets(
id INTEGER PRIMARY KEY, link_id INTEGER NOT NULL REFERENCES links(id) ON DELETE CASCADE,
name TEXT NOT NULL, media_type TEXT NOT NULL, kind TEXT NOT NULL, size INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE asset_chunks(asset_id INTEGER NOT NULL REFERENCES assets(id) ON DELETE CASCADE, ordinal INTEGER NOT NULL, data BLOB NOT NULL, PRIMARY KEY(asset_id,ordinal));
CREATE TABLE dav_revision(id INTEGER PRIMARY KEY CHECK(id=1),value INTEGER NOT NULL,modified INTEGER NOT NULL);
CREATE TABLE dav_ids(id INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT NOT NULL,local_id INTEGER NOT NULL,position INTEGER NOT NULL DEFAULT 2147483647,UNIQUE(kind,local_id));
CREATE TABLE dav_files(name TEXT PRIMARY KEY,size INTEGER NOT NULL,etag TEXT NOT NULL,modified INTEGER NOT NULL,revision INTEGER NOT NULL,owner TEXT NOT NULL);
CREATE TABLE dav_chunks(name TEXT NOT NULL REFERENCES dav_files(name) ON DELETE CASCADE,ordinal INTEGER NOT NULL,data BLOB NOT NULL,PRIMARY KEY(name,ordinal));
CREATE TABLE dav_lock(id INTEGER PRIMARY KEY CHECK(id=1),owner TEXT NOT NULL,modified INTEGER NOT NULL,revision INTEGER NOT NULL);
CREATE TABLE dav_observed(owner TEXT PRIMARY KEY,revision INTEGER NOT NULL);
